/* 언어 선택기에 쓰는 표시 이름 — 항상 해당 언어 표기로(사용자가 자기 언어를 찾기 쉽게) */
const LANG_NAMES = {
  ko: '한국어', en: 'English', ja: '日本語',
  'zh-CN': '简体中文', 'zh-TW': '繁體中文', es: 'Español', de: 'Deutsch',
};

/* 브라우저 언어 태그 → 지원 로케일. 지역 코드까지 맞으면 그대로(zh-TW), 아니면 기본 변형으로
 * 떨어뜨린다(zh → zh-CN, zh-HK/zh-MO → zh-TW, pt-BR 처럼 미지원이면 null). */
function matchLocale(tag) {
  const s = String(tag || '').toLowerCase().replace('_', '-');
  if (!s) return null;
  for (const l of Object.keys(I18N)) if (l.toLowerCase() === s) return l;
  const base = s.split('-')[0];
  if (base === 'zh') return (s === 'zh-tw' || s === 'zh-hk' || s === 'zh-mo' || s.includes('hant')) ? 'zh-TW' : 'zh-CN';
  for (const l of Object.keys(I18N)) if (l.toLowerCase().split('-')[0] === base) return l;
  return null;
}

const LANG = (() => {
  const c = (document.cookie.match(/(?:^|;\s*)lab_lang=([\w-]+)/) || [])[1];
  if (I18N[c]) return c;
  for (const tag of (navigator.languages || [navigator.language || ''])) {
    const m = matchLocale(tag);
    if (m) return m;
  }
  return 'ko';
})();
document.documentElement.lang = LANG;

function t(key, ...args) {
  const v = (I18N[LANG] && I18N[LANG][key]) ?? I18N.ko[key] ?? key;
  return typeof v === 'function' ? v(...args) : v;
}

/* data-i18n="key" 요소 치환 + 토프바에 언어 셀렉터 부착 */
function applyI18n() {
  for (const el of document.querySelectorAll('[data-i18n]')) el.textContent = t(el.dataset.i18n);
  // CSS ::after 로 띄우는 힌트 문구 (lab.html 코드블록) — 사전 값을 CSS 변수로 넘긴다
  document.documentElement.style.setProperty('--run-hint', JSON.stringify(t('runHint')));
  const bar = document.querySelector('.topbar');
  if (bar && !document.getElementById('langSel')) {
    const sel = document.createElement('select');
    sel.id = 'langSel';
    sel.className = 'btn';
    sel.style.cssText = 'padding:4px 8px;font-size:12px;cursor:pointer';
    sel.innerHTML = Object.keys(I18N)
      .map(l => `<option value="${l}">${LANG_NAMES[l] || l}</option>`).join('');
    sel.value = LANG;
    sel.onchange = () => {
      document.cookie = `lab_lang=${sel.value};path=/;max-age=31536000;samesite=lax`;
      location.reload();
    };
    bar.appendChild(sel);
  }
}
document.addEventListener('DOMContentLoaded', applyI18n);

/* ── 뱃지 렌더링 (index/admin 공용) ──
 * 모듈 뱃지 아이콘은 트랙×모듈 번호로 고정, 미정의 트랙(주입 과목)은 🏅 폴백. 트랙 완주는 🏆. */
const BADGE_EMOJI = {
  linux: { 1: '🛡️', 2: '⚙️', 3: '📜', 4: '🐚', 5: '👥', 6: '🛠️', 7: '🌐', 8: '🚑', 9: '📊' },
};
function badgeIcon(track, no) { return (BADGE_EMOJI[track] || {})[no] || '🏅'; }
// b: /api/progress badges[] 항목 — {type:'module',track,no,title,earnedAt} | {type:'track',track,trackTitle,total,earnedAt}
function badgeEl(b, opts = {}) {
  const gold = b.type === 'track';
  const el = document.createElement('span');
  el.className = 'badge-medal' + (gold ? ' gold' : '') + (opts.small ? ' sm' : '') + (opts.locked ? ' locked' : '');
  const coin = document.createElement('span');
  coin.className = 'coin';
  coin.textContent = gold ? '🏆' : badgeIcon(b.track, b.no);
  el.appendChild(coin);
  const label = gold ? `${b.trackTitle || b.track} ${t('trackDoneLbl')}` : b.title;
  if (!opts.small) {
    const lbl = document.createElement('span');
    lbl.className = 'lbl';
    lbl.textContent = label;
    el.appendChild(lbl);
  }
  el.title = label + (b.earnedAt ? ' · ' + new Date(b.earnedAt).toLocaleDateString() : '');
  return el;
}
